<?php
namespace App\Http\Controllers; use App\Models\{AdmissionPeriod,AdmissionWave,ApplicationDocument,ApplicationStatusHistory,ParentProfile,StudentApplication,StudentProfile}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Storage;
class ApplicantController extends Controller { private function app(Request $r){return StudentApplication::firstOrCreate(['user_id'=>$r->user()->id],['status'=>'draft']);} private function editable($a){abort_unless(in_array($a->status,['draft','revision']),403,'Data pendaftaran sudah terkunci.');}
 public function dashboard(Request $r){$app=$this->app($r);return view('dashboard.index',compact('app'));} public function biodata(Request $r){$app=$this->app($r);return view('dashboard.biodata',['app'=>$app,'profile'=>$app->studentProfile??new StudentProfile]);} public function saveBiodata(Request $r){$app=$this->app($r);$this->editable($app);$data=$r->validate(['full_name'=>'required','nik'=>'nullable|digits:16','nisn'=>'nullable|digits_between:8,12','birth_date'=>'nullable|date','gender'=>'required','address'=>'required','birth_place'=>'nullable','religion'=>'nullable','province'=>'nullable','regency'=>'nullable','district'=>'nullable','village'=>'nullable','postal_code'=>'nullable','previous_school'=>'nullable']);$app->studentProfile()->updateOrCreate([], $data);return redirect()->route('applicant.parents')->with('success','Data siswa tersimpan.');} public function parents(Request $r){$app=$this->app($r);return view('dashboard.parents',['app'=>$app,'parent'=>$app->parentProfile??new ParentProfile]);} public function saveParents(Request $r){$app=$this->app($r);$this->editable($app);$data=$r->validate(['father_name'=>'required','father_phone'=>'nullable','mother_name'=>'required','mother_phone'=>'nullable','guardian_name'=>'nullable','guardian_relationship'=>'nullable','guardian_occupation'=>'nullable','guardian_phone'=>'nullable']);$app->parentProfile()->updateOrCreate([], $data);return redirect()->route('applicant.documents')->with('success','Data orang tua tersimpan.');} public function documents(Request $r){$app=$this->app($r);return view('dashboard.documents',compact('app'));} public function upload(Request $r,$type){$app=$this->app($r);$this->editable($app);$rules=['file'=>$type==='student_photo'?'required|image|mimes:jpg,jpeg,png|max:2048':'required|mimes:pdf,jpg,jpeg,png|max:2048'];$r->validate($rules);$old=$app->documents()->where('document_type',$type)->first();if($old)Storage::disk('public')->delete($old->file_path);$file=$r->file('file');$app->documents()->updateOrCreate(['document_type'=>$type],['file_path'=>$file->store('spmb/'.$r->user()->id,'public'),'original_name'=>$file->getClientOriginalName(),'mime_type'=>$file->getMimeType(),'file_size'=>$file->getSize()]);return back()->with('success','Dokumen tersimpan.');} public function removeDocument(Request $r,$id){$app=$this->app($r);$this->editable($app);$doc=$app->documents()->findOrFail($id);Storage::disk('public')->delete($doc->file_path);$doc->delete();return back();} public function review(Request $r){$app=$this->app($r)->load('studentProfile','parentProfile','documents');return view('dashboard.review',compact('app'));} public function submit(Request $r){$app=$this->app($r);$this->editable($app);abort_unless($app->studentProfile&&$app->parentProfile&&$app->documents()->whereIn('document_type',['student_photo','family_card','birth_certificate'])->count()===3,422,'Lengkapi data dan dokumen wajib.');$period=AdmissionPeriod::where('is_active',true)->first();$wave=$period?AdmissionWave::where('admission_period_id',$period->id)->where('is_active',true)->whereDate('start_date','<=',today())->whereDate('end_date','>=',today())->first():null;abort_unless($wave,422,'Pendaftaran SPMB saat ini belum dibuka.');DB::transaction(function()use($app,$period,$wave){
$period=AdmissionPeriod::whereKey($period->id)->where('is_active',true)->lockForUpdate()->first();
abort_unless($period,422,'Periode SPMB tidak lagi aktif.');
$wave=AdmissionWave::whereKey($wave->id)->where('admission_period_id',$period->id)->where('is_active',true)->whereDate('start_date','<=',today())->whereDate('end_date','>=',today())->lockForUpdate()->first();
abort_unless($wave,422,'Gelombang SPMB tidak lagi tersedia.');
$year=substr($period->academic_year,0,4);$number='SPMB-'.$year.'-'.str_pad((string)(StudentApplication::lockForUpdate()->whereNotNull('registration_number')->count()+1),4,'0',STR_PAD_LEFT);$app->update(['admission_period_id'=>$period->id,'admission_wave_id'=>$wave->id,'registration_number'=>$number,'status'=>'submitted','submitted_at'=>now()]);$app->statusHistories()->create(['status'=>'submitted','note'=>'Pendaftaran dikirim oleh pendaftar.']);});return redirect()->route('applicant.status');} public function status(Request $r){$app=$this->app($r)->load('studentProfile','period','wave','statusHistories');return view('dashboard.status',compact('app'));} }
